// =============================================================
// *** R INTERPRETER ITEM — eval ***
// A complete fake is impossible without an R interpreter.
// Register a Python callback via register_eval_fn() before use.
//
// eval(SEXP expr, SEXP rho) evaluates an R language object (LANGSXP) in
// an R environment (ENVSXP).  In the fake runtime, the entire evaluation
// is replaced by a Python-registered function pointer g_eval_fn.
//
// Affected code paths:
//   rpart_callback.c:112  value    = eval(expr2, rho);  [rpart_callback1]
//   rpart_callback.c:146  goodness = eval(expr1, rho);  [rpart_callback2]
//
// These callbacks are only invoked when rpart() is called with method=4
// (user-defined splits).  All standard rpart methods (anova, poisson,
// class, exp) never reach either call site.
//
// Python dispatch key: the expr argument (expr1 vs. expr2) identifies
// which computation to perform.  Python compares the received expr pointer
// against the known expr1/expr2 handles stored during init_rpcallback to
// select the correct evaluation branch.
//
// Expected return value: a heap-allocated REALSXP SEXP whose data field
// contains the result double[] array and whose length field is set to:
//   eval(expr2, rho):  length == 1 + rsave   (deviance + mean output)
//   eval(expr1, rho):  length == 2*(n-1)     (ncat==0, continuous splits)
//                   or 2*ncategories_present-1 (ncat>0, categorical splits)
//
// The C code reads REAL(result) immediately after eval() returns and copies
// the doubles into the caller-supplied output array (z[] or good[]).
// The SEXP need only remain alive until rpart_callback1/2 returns.
// =============================================================

// --- Core fake implementation ---

// -----------------------------------------------------------------------
// eval_fn_t — the function pointer type for the Python-registered callback.
//
// Signature matches the real Rf_eval declaration at Rinternals.h line 531:
//   SEXP Rf_eval(SEXP expr, SEXP rho);
// -----------------------------------------------------------------------
#ifndef FAKE_EVAL_FN_DEFINED
#define FAKE_EVAL_FN_DEFINED

typedef SEXP (*eval_fn_t)(SEXP expr, SEXP rho);

// g_eval_fn — the registered Python callback.
// C++17 inline variable: one shared definition across all translation units
// that include this header.  All TUs read and write the same g_eval_fn.
// register_eval_fn() called from Python updates this single instance, so
// Rf_eval() in any TU sees the registered callback immediately.
inline eval_fn_t g_eval_fn = nullptr;

// register_eval_fn — called once from Python (via ctypes) before any
// invocation of rpart() with method=4.
// C linkage ensures ctypes can locate the symbol by name in the shared lib.
extern "C" inline void register_eval_fn(eval_fn_t fn) {
    g_eval_fn = fn;
}

// Rf_eval — the fake implementation.
//
// Pattern P1 (rpart_callback.c:112):
//   value = eval(expr2, rho);   // expr2 stored by init_rpcallback
//   if (!isReal(value)) error(_("return value not a vector"));
//   if (LENGTH(value) != (1 + rsave)) error(_("returned value is the wrong length"));
//   dptr = REAL(value);
//   for (i = 0; i <= rsave; i++) z[i] = dptr[i];
//
// Pattern P2 (rpart_callback.c:146):
//   goodness = eval(expr1, rho);   // expr1 stored by init_rpcallback
//   if (!isReal(goodness)) error(_("the expression expr1 did not return a vector!"));
//   j = LENGTH(goodness);
//   dptr = REAL(goodness);
//   // ... copies data into good[] ...
//
// Both patterns are covered by this single stub; the caller distinguishes
// them by the expr argument value (expr2 vs. expr1).
//
// If g_eval_fn is null (Python did not register a callback), Rf_eval throws
// RError.  The exception propagates through rpart_callback1/rpart_callback2
// through rpart's internal fitting loop up to the .Call-boundary wrapper
// (rpart_wrapper), where it is caught, the message is stored, and the
// wrapper returns nullptr to Python (Invariant 1).
//
// [[noreturn]] is NOT applied here: Rf_eval returns normally when a
// callback is registered.  The throw-on-null path is the exceptional case.
inline SEXP Rf_eval(SEXP expr, SEXP rho) {
    if (!g_eval_fn)
        throw RError(
            "eval: Python callback not registered. "
            "User-defined splits (method=4) require registration "
            "via register_eval_fn() before calling rpart() with method=4.");
    return g_eval_fn(expr, rho);
}

#endif // FAKE_EVAL_FN_DEFINED

